<?php
if(!defined('ABSPATH')){exit;}
final class Orion_OpenRouter_Client implements Orion_AI_Provider{
 private const ENDPOINT='https://openrouter.ai/api/v1/chat/completions';private string $api_key;private string $model;private int $timeout;private int $max_tokens;public function __construct(string $key,string $model,int $timeout=20,int $max_tokens=900){$this->api_key=trim($key);$this->model=trim($model)?:'openrouter/auto';$this->timeout=max(5,min(60,$timeout));$this->max_tokens=max(200,min(4000,$max_tokens));}
 public function chat(array $messages,array $tools=array()):array{$started=microtime(true);if($this->api_key==='')return$this->meta(array('ok'=>false,'error'=>'OpenRouter API key is not configured.'),$started);$body=array('model'=>$this->model,'messages'=>$messages,'temperature'=>0.2,'max_tokens'=>$this->max_tokens);if($tools){$body['tools']=$tools;$body['tool_choice']='required';$body['parallel_tool_calls']=false;}$response=wp_remote_post(self::ENDPOINT,array('timeout'=>$this->timeout,'redirection'=>0,'headers'=>array('Authorization'=>'Bearer '.$this->api_key,'Content-Type'=>'application/json','HTTP-Referer'=>home_url('/'),'X-OpenRouter-Title'=>get_bloginfo('name').' AI Assistant'),'body'=>wp_json_encode($body)));if(is_wp_error($response))return$this->meta(array('ok'=>false,'error'=>'The AI service could not be reached. Please try again.','status'=>0),$started);$code=(int)wp_remote_retrieve_response_code($response);$json=json_decode(wp_remote_retrieve_body($response),true);$raw=is_array($json)?(string)($json['error']['message']??''):'';if($code<200||$code>=300){$public=match($code){401=>'OpenRouter authentication failed.',402=>'OpenRouter credit is unavailable.',429=>'The AI service is busy or rate limited. Please try again shortly.',default=>'The AI service returned an error. Please try again.'};return$this->meta(array('ok'=>false,'error'=>$public,'detail'=>sanitize_text_field($raw),'status'=>$code),$started);}$message=$json['choices'][0]['message']??null;if(!is_array($message))return$this->meta(array('ok'=>false,'error'=>'The AI service returned an invalid response.'),$started);return$this->meta(array('ok'=>true,'message'=>$message,'usage'=>is_array($json['usage']??null)?$json['usage']:array()),$started);}
 private function meta(array $result,float $started):array{$result['provider']='openrouter';$result['model']=$this->model;$result['duration_ms']=(int)round((microtime(true)-$started)*1000);return$result;}
}
